    howtoplayPanelTitle: 'How to Play',
    htpMove: '**{key:move}** to move, **Mouse** to look, **{key:jump}** to jump, **{key:sprint}** to sprint.',
    htpRules: 'Play fair - no cheating, exploiting bugs, or messing with leaderboard scores. Keep your nickname clean and respectful. Found a bug or someone breaking the rules? Report it on Discord.',
    htpWavesShoot: "Pick your weapon when the run starts. **Left Click** to shoot (hold it for automatic guns), hold **Right Click** to aim down the sights (let go to stop), **{key:reload}** to reload and **{key:inspectWeapon}** to inspect your gun. Hold **Left Click** on a block close by to break it - stone takes longer than wood. Every gun has its own damage, fire rate and ammo - Loot Chests around the city refill it and heal you.",
    htpWavesCamp: "You start in the walled camp, where zombies can't get in. Look at an NPC and press **{key:use}** to talk: the Trader sells supplies, the Upgrader makes your gun better, Ammo Refill fills you up, and the Quest Board pays coins for quests.",
    htpWavesWaves: "Zombies come in waves - more, faster and tougher each time - and find their way to you around walls and up stairs and ladders. Later waves bring skeletons too, climbing up out of the ground. Earn coins from kills and cleared waves, and see how many waves you can survive. Before you press Play, pick a difficulty, game mode and mutators in Game Mode; every run earns Points to spend in Upgrades. Each wave needs a number of kills - zombies keep coming from all around until you get them, and their bodies fade away within a minute (fire burns them away faster).",
