    prestigeCostLine: '转生等级 {level} 需要 {cost} 点数 - 你现在有 {have}。',
    prestigeConfirm: '转生会将你的点数和所有永久升级永久清零,以换取此后每局获得的点数永久 +10%(可与每次转生叠加)。此操作无法撤销。是否继续?',
    prestigeComplete: '已达成转生 {level}。点数和永久升级已重置 —— 此后每局点数 +{bonus}%。',
    metaIronWill: '+15 最大生命值,+15 最大护甲(永久)',
