    eventBannerWinter: 'शहर पर एक ठंडी लहर छा गई है।',
    howtoplayPanelTitle: 'कैसे खेलें',
    htpMove: 'चलने के लिए **{key:move}**, देखने के लिए **Mouse**, कूदने के लिए **{key:jump}**, दौड़ने के लिए **{key:sprint}**।',
    htpRules: 'ईमानदारी से खेलो - कोई चीटिंग, बग का फ़ायदा उठाना, या लीडरबोर्ड स्कोर से छेड़छाड़ नहीं। अपना निकनेम साफ़-सुथरा और सम्मानजनक रखो। कोई बग मिला या कोई नियम तोड़ रहा है? Discord पर रिपोर्ट करो।',
    htpWavesShoot: "राउंड शुरू होने पर अपना हथियार चुनें। गोली चलाने के लिए **लेफ्ट क्लिक** (ऑटोमैटिक बंदूकों के लिए दबाए रखें), निशाना लगाने के लिए **राइट क्लिक** दबाए रखें (छोड़ने पर रुक जाता है), रीलोड के लिए **{key:reload}** और बंदूक देखने के लिए **{key:inspectWeapon}**। पास के किसी ब्लॉक पर **लेफ्ट क्लिक** दबाए रखने से वह टूट जाता है - पत्थर लकड़ी से ज़्यादा समय लेता है। हर बंदूक का नुकसान, फ़ायर रेट और गोलियाँ अलग हैं - शहर में लूट की पेटियाँ इन्हें भरती हैं और आपको ठीक करती हैं।",
    htpWavesCamp: "आप दीवारों वाले कैंप में शुरू करते हैं, जहाँ ज़ॉम्बी नहीं आ सकते। किसी NPC को देखें और बात करने के लिए **{key:use}** दबाएँ: व्यापारी सामान बेचता है, अपग्रेडर आपकी बंदूक बेहतर बनाता है, गोला-बारूद भराई गोलियाँ भरती है, और क्वेस्ट बोर्ड क्वेस्ट के लिए सिक्के देता है।",
    htpWavesWaves: "ज़ॉम्बी लहरों में आते हैं - हर बार ज़्यादा, तेज़ और मज़बूत - और दीवारों के चारों ओर, सीढ़ियों और सीढ़ियों पर चढ़कर आप तक पहुँचते हैं। बाद की लहरों में ज़मीन से निकलते कंकाल भी आते हैं। मारने और लहर साफ़ करने पर सिक्के कमाएँ, और देखें आप कितनी लहरें झेल पाते हैं। Play दबाने से पहले, Game Mode में कठिनाई, गेम मोड और म्यूटेटर चुनें; हर रन से पॉइंट्स मिलते हैं जिन्हें अपग्रेड्स में खर्च कर सकते हैं। हर वेव में तय संख्या में किल चाहिए - जब तक आप उन्हें पूरा न करें, ज़ॉम्बी चारों तरफ़ से आते रहते हैं, और उनके शरीर एक मिनट में गायब हो जाते हैं (आग से और जल्दी)।",
