    prestigeConfirm: 'El Prestigio reinicia tus Puntos y todas las Mejoras Permanentes a cero, permanentemente, a cambio de +10% de Puntos ganados por partida a partir de ahora (se acumula con cada Prestigio). Esto no se puede deshacer. ¿Continuar?',
