    milestoneKillsToast: '{n} bajas totales. Los infectados empiezan a reconocerte.',
    eventBannerHalloween: 'Algo perverso se agita entre las ruinas esta semana...',
    eventBannerWinter: 'Una ola de frío se ha asentado sobre la ciudad.',
    howtoplayPanelTitle: 'Cómo Jugar',
    htpMove: '**{key:move}** para moverte, **Ratón** para mirar, **{key:jump}** para saltar, **{key:sprint}** para correr.',
    htpRules: 'Juega limpio - nada de trampas, explotar fallos, o manipular las puntuaciones de la clasificación. Mantén tu apodo limpio y respetuoso. ¿Encontraste un fallo o a alguien rompiendo las reglas? Repórtalo en Discord.',
    htpWavesShoot: "Elige tu arma al empezar la partida. **Clic izquierdo** para disparar (mantenlo pulsado con las armas automáticas), mantén el **clic derecho** para apuntar (suéltalo para dejar de apuntar), **{key:reload}** para recargar y **{key:inspectWeapon}** para inspeccionar tu arma. Mantén el **clic izquierdo** sobre un bloque cercano para romperlo: la piedra tarda más que la madera. Cada arma tiene su propio daño, cadencia y munición - los Cofres de Botín de la ciudad la rellenan y te curan.",
    htpWavesCamp: "Empiezas en el campamento amurallado, donde los zombis no pueden entrar. Mira a un NPC y pulsa **{key:use}** para hablar: el Comerciante vende suministros, el Mejorador mejora tu arma, la Recarga de Munición te llena y el Tablón de Misiones paga monedas por misiones.",
    htpWavesWaves: "Los zombis llegan en oleadas - más, más rápidos y más duros cada vez - y te encuentran rodeando paredes y subiendo escaleras y escalas. Las oleadas posteriores también traen esqueletos que salen del suelo. Gana monedas por bajas y oleadas superadas, y mira cuántas oleadas aguantas. Antes de pulsar Jugar, elige dificultad, modo de juego y mutadores en Modo de Juego; cada partida te da Puntos para gastar en Mejoras. Cada oleada necesita un número de muertes: los zombis siguen llegando desde todas partes hasta que lo consigues, y sus cuerpos desaparecen en un minuto (el fuego los quema más rápido).",
